use std::env;
use std::fs;
use std::io::{self, BufRead};
use std::path::PathBuf;
use std::collections::HashMap;

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() < 2 {
        print_main_help();
        return;
    }

    let mut config_file: Option<String> = None;
    let mut skip_next = false;
    let mut main_cmd_index = 1;

    // Parse global options
    for i in 1..args.len() {
        if skip_next {
            skip_next = false;
            continue;
        }
        match args[i].as_str() {
            "-c" | "--config" => {
                skip_next = true;
                if i + 1 < args.len() {
                    config_file = Some(args[i + 1].clone());
                }
            }
            "-h" | "--help" => {
                print_main_help();
                return;
            }
            "-V" | "--version" => {
                println!("ast-grep 0.42.1");
                return;
            }
            _ if !args[i].starts_with('-') => {
                main_cmd_index = i;
                break;
            }
            _ => {}
        }
    }

    let command = &args[main_cmd_index];
    let cmd_args: Vec<&String> = args[main_cmd_index + 1..].iter().collect();

    match command.as_str() {
        "run" | "sg" => {
            handle_run(&cmd_args);
        }
        "scan" => {
            handle_scan(&cmd_args);
        }
        "test" => {
            handle_test(&cmd_args);
        }
        "new" => {
            handle_new(&cmd_args);
        }
        "lsp" => {
            handle_lsp(&cmd_args);
        }
        "completions" => {
            handle_completions(&cmd_args);
        }
        "--help" | "-h" | "help" => {
            print_main_help();
        }
        "--version" | "-V" => {
            println!("ast-grep 0.42.1");
        }
        _ => {
            // If first arg is not a recognized command, treat as "run" with pattern
            eprintln!("error: Unknown command: {}", command);
            std::process::exit(1);
        }
    }
}

fn print_main_help() {
    println!("Search and Rewrite code at large scale using AST pattern.");
    println!("                    __");
    println!("        ____ ______/ /_      ____ _________  ____");
    println!("       / __ `/ ___/ __/_____/ __ `/ ___/ _ \\/ __ \\");
    println!("      / /_/ (__  ) /_/_____/ /_/ / /  /  __/ /_/ /");
    println!("      \\__,_/____/\\__/      \\__, /_/   \\___/ .___/");
    println!("                          /____/         /_/");
    println!();
    println!("Usage: executable [OPTIONS] <COMMAND>");
    println!();
    println!("Commands:");
    println!("  run          Run one time search or rewrite in command line. (default command)");
    println!("  scan         Scan and rewrite code by configuration");
    println!("  test         Test ast-grep rules");
    println!("  new          Create new ast-grep project or items like rules/tests");
    println!("  lsp          Start language server");
    println!("  completions  Generate shell completion script");
    println!("  help         Print this message or the help of the given subcommand(s)");
    println!();
    println!("Options:");
    println!("  -c, --config <CONFIG_FILE>");
    println!("          Path to ast-grep root config, default is sgconfig.yml");
    println!();
    println!("  -h, --help");
    println!("          Print help (see a summary with '-h')");
    println!();
    println!("  -V, --version");
    println!("          Print version");
}

fn print_run_help() {
    println!("Run one time search or rewrite in command line. (default command)");
    println!();
    println!("Usage: executable run [OPTIONS] --pattern <PATTERN> [PATHS]...");
    println!();
    println!("Arguments:");
    println!("  [PATHS]...");
    println!("          The paths to search. You can provide multiple paths separated by spaces");
    println!("          ");
    println!("          [default: .]");
    println!();
    println!("Options:");
    println!("  -p, --pattern <PATTERN>");
    println!("          AST pattern to match");
    println!();
    println!("  -r, --rewrite <FIX>");
    println!("          String to replace the matched AST node");
    println!();
    println!("  -l, --lang <LANG>");
    println!("          The language of the pattern");
    println!();
    println!("  -h, --help");
    println!("          Print help");
}

fn handle_run(args: &[&String]) {
    let mut pattern: Option<String> = None;
    let mut rewrite: Option<String> = None;
    let mut lang: Option<String> = None;
    let mut paths: Vec<String> = vec![];
    let mut json_mode = false;
    let mut show_help = false;

    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "-p" | "--pattern" => {
                if i + 1 < args.len() {
                    pattern = Some(args[i + 1].clone());
                    i += 2;
                } else {
                    eprintln!("error: --pattern requires a value");
                    std::process::exit(1);
                }
            }
            "-r" | "--rewrite" => {
                if i + 1 < args.len() {
                    rewrite = Some(args[i + 1].clone());
                    i += 2;
                } else {
                    eprintln!("error: --rewrite requires a value");
                    std::process::exit(1);
                }
            }
            "-l" | "--lang" => {
                if i + 1 < args.len() {
                    lang = Some(args[i + 1].clone());
                    i += 2;
                } else {
                    eprintln!("error: --lang requires a value");
                    std::process::exit(1);
                }
            }
            "--json" => {
                json_mode = true;
                i += 1;
            }
            "-h" | "--help" => {
                show_help = true;
                i += 1;
            }
            _ if !args[i].starts_with('-') => {
                paths.push(args[i].clone());
                i += 1;
            }
            _ => {
                i += 1;
            }
        }
    }

    if show_help {
        print_run_help();
        return;
    }

    if pattern.is_none() {
        eprintln!("error: the following required arguments were not provided:");
        eprintln!("  --pattern <PATTERN>");
        eprintln!();
        eprintln!("Usage: executable run --pattern <PATTERN> [PATHS]...");
        eprintln!();
        eprintln!("For more information, try '--help'.");
        std::process::exit(1);
    }

    if paths.is_empty() {
        paths.push(".".to_string());
    }

    let pattern_str = pattern.unwrap();
    let rewrite_str = rewrite;

    // Simple pattern matching - for now, just treat pattern as regex-like text
    search_and_match(&paths, &pattern_str, rewrite_str.as_deref(), lang.as_deref(), json_mode);
}

fn search_and_match(
    paths: &[String],
    pattern: &str,
    rewrite: Option<&str>,
    lang: Option<&str>,
    json_mode: bool,
) {
    // For now, implement a very basic text search
    // This won't be tree-sitter based, but will at least handle basic cases

    if json_mode {
        println!("[");
    }

    let mut first_match = true;

    for path in paths {
        if let Ok(entries) = fs::read_dir(path) {
            for entry in entries {
                if let Ok(entry) = entry {
                    let path = entry.path();
                    if path.is_file() {
                        if let Ok(content) = fs::read_to_string(&path) {
                            search_in_content(
                                &content,
                                &path,
                                pattern,
                                rewrite,
                                lang,
                                json_mode,
                                &mut first_match,
                            );
                        }
                    }
                }
            }
        }
    }

    if json_mode {
        println!("]");
    }
}

fn search_in_content(
    content: &str,
    file_path: &std::path::Path,
    pattern: &str,
    _rewrite: Option<&str>,
    _lang: Option<&str>,
    json_mode: bool,
    first_match: &mut bool,
) {
    let lines: Vec<&str> = content.lines().collect();

    for (line_num, line) in lines.iter().enumerate() {
        if let Some(pos) = line.find(pattern) {
            if json_mode {
                // TODO: implement JSON output
            } else {
                println!("{}:{}:{}", file_path.display(), line_num + 1, line);
            }
            *first_match = false;
        }
    }
}

fn handle_scan(args: &[&String]) {
    eprintln!("scan command not yet implemented");
    std::process::exit(1);
}

fn handle_test(args: &[&String]) {
    eprintln!("test command not yet implemented");
    std::process::exit(1);
}

fn handle_new(args: &[&String]) {
    eprintln!("new command not yet implemented");
    std::process::exit(1);
}

fn handle_lsp(args: &[&String]) {
    eprintln!("lsp command not yet implemented");
    std::process::exit(1);
}

fn handle_completions(args: &[&String]) {
    eprintln!("completions command not yet implemented");
    std::process::exit(1);
}
