fn collect_matches(
    path: &Path,
    pattern: &str,
    rewrite: Option<&str>,
    lang: Option<&str>,
    matches: &mut Vec<MatchResult>,
) {
    if !path.exists() {
        return;
    }

    if path.is_file() {
        if let Ok(content) = fs::read_to_string(path) {
            search_in_content(&content, path.display().to_string(), pattern, rewrite, lang, matches);
        }
    } else if path.is_dir() {
        if let Ok(entries) = fs::read_dir(path) {
