            }
        }
    }
}

fn search_in_content(
    content: &str,
    file: String,
    pattern: &str,
    rewrite: Option<&str>,
    lang: Option<&str>,
    matches: &mut Vec<MatchResult>,
) {
    for (line_num, line) in content.lines().enumerate() {
        // Try to match pattern with variables
        if let Some((matched_text, vars)) = match_pattern_with_vars(line, pattern) {
            let replacement = rewrite.map(|r| apply_substitution(r, &vars));

            // For simple patterns without variables, try to find it
            if pattern.contains('$') {
                matches.push(MatchResult {
                    file: file.clone(),
                    line_num: line_num + 1,
                    line_text: line.to_string(),
                    matched_text,
                    replacement,
                    start_col: 0, // Simplified
                    end_col: 0,   // Simplified
                });
            }
        } else if !pattern.contains('$') && line.contains(pattern) {
            // Simple substring match
            let replacement = rewrite.map(|r| r.to_string());
            matches.push(MatchResult {
                file: file.clone(),
                line_num: line_num + 1,
                line_text: line.to_string(),
                matched_text: pattern.to_string(),
                replacement,
                start_col: 0,
                end_col: 0,
            });
        }
    }
}

fn match_pattern_with_vars(text: &str, pattern: &str) -> Option<(String, HashMap<String, String>)> {
