#[derive(Clone)]
struct MatchResult {
    file: String,
    line_num: usize,
    line_text: String,
    replacement: Option<String>,
}

fn search_files(
    paths: &[String],
    pattern: &str,
    rewrite: Option<&str>,
    _lang: Option<&str>,
    json_output: bool,
) {
    let mut matches = Vec::new();

    for path_str in paths {
        let path = Path::new(path_str);
        collect_matches(path, pattern, rewrite, &mut matches);
    }

    if json_output {
        print_json_matches(&matches);
    } else {
        print_text_matches(&matches);
    }
}

fn collect_matches(
    path: &Path,
    pattern: &str,
    rewrite: Option<&str>,
    matches: &mut Vec<MatchResult>,
) {
    if !path.exists() {
        return;
    }

    if path.is_file() {
        if let Ok(content) = fs::read_to_string(path) {
            search_in_content(&content, path.display().to_string(), pattern, rewrite, matches);
        }
    } else if path.is_dir() {
        if let Ok(entries) = fs::read_dir(path) {
            for entry in entries {
                if let Ok(entry) = entry {
                    collect_matches(&entry.path(), pattern, rewrite, matches);
                }
            }
        }
    }
}

fn search_in_content(
    content: &str,
    file: String,
    pattern: &str,
    rewrite: Option<&str>,
    matches: &mut Vec<MatchResult>,
) {
    for (line_num, line) in content.lines().enumerate() {
        // Check if pattern contains variables
        if pattern.contains('$') {
            // Try to match pattern with variables
            if let Some((_matched_text, vars)) = match_pattern_with_vars(line, pattern) {
                let replacement = rewrite.map(|r| apply_substitution(r, &vars));
                matches.push(MatchResult {
                    file: file.clone(),
                    line_num: line_num + 1,
                    line_text: line.to_string(),
                    replacement,
                });
            }
        } else {
            // Simple substring match
            if line.contains(pattern) {
                let replacement = rewrite.map(|r| r.to_string());
                matches.push(MatchResult {
                    file: file.clone(),
                    line_num: line_num + 1,
                    line_text: line.to_string(),
                    replacement,
                });
            }
        }
    }
}

fn match_pattern_with_vars(text: &str, pattern: &str) -> Option<(String, HashMap<String, String>)> {
    let mut vars: HashMap<String, String> = HashMap::new();

    // Split pattern and text by whitespace
    let pattern_parts: Vec<&str> = pattern.split_whitespace().collect();
    if pattern_parts.is_empty() {
        return None;
    }

    let words: Vec<&str> = text.split_whitespace().collect();

    // Try to match pattern parts with words
    let mut pattern_idx = 0;
    let mut word_idx = 0;
    let mut matched_text = String::new();

    while pattern_idx < pattern_parts.len() && word_idx < words.len() {
        let pat = pattern_parts[pattern_idx];
        let word = words[word_idx];

        if pat.starts_with('$') {
            // This is a variable, capture it
            let var_name = pat[1..].to_string();
            vars.insert(var_name, word.to_string());
            if !matched_text.is_empty() {
                matched_text.push(' ');
            }
            matched_text.push_str(word);
            pattern_idx += 1;
            word_idx += 1;
        } else if pat == word {
            // Exact match
            if !matched_text.is_empty() {
                matched_text.push(' ');
            }
            matched_text.push_str(word);
            pattern_idx += 1;
            word_idx += 1;
        } else {
            // No match
            return None;
        }
    }

    if pattern_idx == pattern_parts.len() && !vars.is_empty() {
        Some((matched_text, vars))
    } else {
        None
    }
}

fn apply_substitution(template: &str, vars: &HashMap<String, String>) -> String {
    let mut result = template.to_string();
    for (key, value) in vars {
        let pattern = format!("${}", key);
        result = result.replace(&pattern, value);
    }
    result
}

fn print_text_matches(matches: &[MatchResult]) {
    for m in matches {
        println!("{}:{}:{}", m.file, m.line_num, m.line_text);
    }
}

fn print_json_matches(matches: &[MatchResult]) {
    println!("[");
    for (i, m) in matches.iter().enumerate() {
        if i > 0 {
            println!(",");
        }
        println!("{{");
        println!("  \"text\": \"{}\",", escape_json_string(&m.line_text));
        println!("  \"file\": \"{}\",", escape_json_string(&m.file));
        println!("  \"line\": {}", m.line_num);
        if let Some(repl) = &m.replacement {
            println!(",");
            println!("  \"replacement\": \"{}\"", escape_json_string(repl));
        }
        print!("}}");
    }
    if !matches.is_empty() {
        println!();
    }
    println!("]");
}

fn escape_json_string(s: &str) -> String {
    let mut result = String::new();
    for c in s.chars() {
        match c {
            '"' => result.push_str("\\\""),
            '\\' => result.push_str("\\\\"),
            '\n' => result.push_str("\\n"),
            '\r' => result.push_str("\\r"),
            '\t' => result.push_str("\\t"),
            _ => result.push(c),
        }
    }
    result
}
